import{_ as t,J as s,b as i,e as o,a8 as n,f as r,L as c}from"./chunks/framework.C-MVLAPI.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_Paths","entity":"TCustomPath","kind":"Class","abstract":true,"declaration":"TCustomPath = class abstract(TThreadPersistent)","inheritance":["TObject","TPersistent","TPlainInterfacedPersistent","TNotifiablePersistent","TThreadPersistent","TCustomPath"],"summary":"Abstract base class for vector path builders, managing coordinate states and vector path directives.","date":1788612405000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_Paths/TCustomPath/index.md","filePath":"api/GR32_Paths/Classes/TCustomPath/index.md","lastUpdated":1788612405000,"timestamp":1788612405000,"datetime":"2026-09-05T12:46:45.000Z","contributors":[]}'),d={name:"api/GR32_Paths/TCustomPath/index.md"};function l(h,e,p,u,m,P){const a=s("ApiMembers");return i(),o("div",null,[e[0]||(e[0]=n('<h2 id="declaration" tabindex="-1">Declaration <a class="header-anchor" href="#declaration" aria-label="Permalink to &quot;Declaration&quot;">​</a></h2><div class="language-pascal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TCustomPath = </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> abstract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(TThreadPersistent)</span></span></code></pre></div><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>TCustomPath</code> is the abstract base class for vector path construction in Graphics32. It establishes a vector drawing interface inspired by SVG path commands, offering absolute and relative directives for straight lines, cubic Bezier curves, quadratic (conic) Bezier curves, circular arcs, rectangles, rounded rectangles, ellipses, circles, polylines, and polygons.</p><p>Key features of <code>TCustomPath</code> include:</p><ul><li><strong>Path Position Management</strong>: Maintains the active drawing coordinate in <a href="/api/GR32_Paths/TCustomPath/CurrentPoint">CurrentPoint</a> updated by movement, line, and curve commands.</li><li><strong>Absolute and Relative Commands</strong>: Provides paired absolute (e.g. <code>LineTo</code>, <code>CurveTo</code>, <code>ConicTo</code>) and relative commands (e.g. <code>LineToRelative</code>, <code>CurveToRelative</code>, <code>ConicToRelative</code>).</li><li><strong>Smooth Curve Continuation</strong>: Automatically reflects control points when chaining smooth cubic (<code>CurveTo(C2, P)</code>) or quadratic (<code>ConicTo(P)</code>) Bezier segments.</li><li><strong>Geometric Primitives</strong>: Provides convenient methods for adding shapes such as <a href="/api/GR32_Paths/TCustomPath/Rectangle">Rectangle</a>, <a href="/api/GR32_Paths/TCustomPath/RoundRect">RoundRect</a>, <a href="/api/GR32_Paths/TCustomPath/Ellipse">Ellipse</a>, <a href="/api/GR32_Paths/TCustomPath/Circle">Circle</a>, <a href="/api/GR32_Paths/TCustomPath/Polygon">Polygon</a>, and <a href="/api/GR32_Paths/TCustomPath/PolyPolygon">PolyPolygon</a>.</li></ul><p>Derived classes (such as <a href="/api/GR32_Paths/TFlattenedPath/">TFlattenedPath</a> and <a href="/api/GR32_Paths/TCanvas32/">TCanvas32</a>) override internal point generation routines (<code>AddPoint</code>, <code>EndPath</code>) to convert high-level path commands into flattened polygonal vertex lists or render them directly onto bitmap targets.</p>',7)),r("p",null,[c(a,{type:"members"})])])}const v=t(d,[["render",l]]);export{g as __pageData,v as default};
